1	package main
2	
3	import (
4		"crypto/sha256"
5		"encoding/csv"
6		"encoding/hex"
7		"fmt"
8		"io"
9		"os"
10		"sort"
11		"strconv"
12		"strings"
13		"time"
14	)
15	
16	// 用量导入文件（CSV，UTF-8，首行为固定表头，之后每行一条用量）：
17	//
18	//	usage_id,customer_id,time,quantity
19	//	u-001,cust-1,2026-09-15T10:00:00Z,100
20	//
21	//	usage_id   全局唯一用量标识，非空
22	//	customer_id 必须是已登记的客户标识
23	//	time       RFC3339 时间，如 2026-09-15T10:00:00Z 或 2026-09-15T18:00:00+08:00
24	//	quantity   正整数数量（有符号 64 位整数范围内）
25	const usageHeader = "usage_id,customer_id,time,quantity"
26	
27	// runCmd 解析并执行子命令。业务/用法错误通过 error 返回，由 main 统一
28	// 写入标准错误并以非零状态退出。
29	func runCmd(args []string, dataDir string) error {
30		switch args[0] {
31		case "customer":
32			if len(args) < 2 {
33				return usageError("缺少子命令，应为：customer add <标识> <名称> <单价分>")
34			}
35			switch args[1] {
36			case "add":
37				if len(args) != 5 {
38					return usageError("用法：customer add <标识> <名称> <单价分>")
39				}
40				return cmdCustomerAdd(dataDir, args[2], args[3], args[4])
41			default:
42				return usageError("未知 customer 子命令 %q；可用：add", args[1])
43			}
44	
45		case "usage":
46			if len(args) < 2 {
47				return usageError("缺少子命令，应为：usage import <文件>")
48			}
49			switch args[1] {
50			case "import":
51				if len(args) != 3 {
52					return usageError("用法：usage import <文件>（- 表示标准输入）")
53				}
54				return cmdUsageImport(dataDir, args[2])
55			default:
56				return usageError("未知 usage 子命令 %q；可用：import", args[1])
57			}
58	
59		case "bill":
60			if len(args) < 2 {
61				return usageError("缺少子命令，应为：bill settle|show <客户标识> <YYYY-MM>")
62			}
63			switch args[1] {
64			case "settle":
65				if len(args) != 4 {
66					return usageError("用法：bill settle <客户标识> <YYYY-MM>")
67				}
68				return cmdBillSettle(dataDir, args[2], args[3])
69			case "show":
70				if len(args) != 4 {
71					return usageError("用法：bill show <客户标识> <YYYY-MM>")
72				}
73				return cmdBillShow(dataDir, args[2], args[3])
74			default:
75				return usageError("未知 bill 子命令 %q；可用：settle、show", args[1])
76			}
77	
78		default:
79			return usageError("未知命令 %q；可用：customer、usage、bill", args[0])
80		}
81	}
82	
83	type usageErrorf string
84	
85	func (e usageErrorf) Error() string { return string(e) }
86	
87	func usageError(format string, a ...any) error {
88		return usageErrorf(fmt.Sprintf(format, a...))
89	}
90	
91	func cmdCustomerAdd(dir, id, name, priceText string) error {
92		if strings.TrimSpace(id) == "" {
93			return fmt.Errorf("客户标识不能为空")
94		}
95		if strings.TrimSpace(name) == "" {
96			return fmt.Errorf("客户名称不能为空")
97		}
98		price, err := parsePrice(priceText)
99		if err != nil {
100			return err
101		}
102	
103		s, err := loadStore(dir)
104		if err != nil {
105			return err
106		}
107		if _, exists := s.Customers[id]; exists {
108			return fmt.Errorf("客户标识 %q 已存在，客户单价创建后不可修改", id)
109		}
110		s.Customers[id] = &customer{ID: id, Name: name, Price: price}
111		if err := s.save(); err != nil {
112			return err
113		}
114		fmt.Fprintf(stdout, "已登记客户 %q（%s），固定单价 %d 分（%s）\n", id, name, price, moneyFen(price))
115		return nil
116	}
117	
118	func parsePrice(text string) (int64, error) {
119		text = strings.TrimSpace(text)
120		price, err := strconv.ParseInt(text, 10, 64)
121		if err != nil {
122			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
123		}
124		if price < 0 {
125			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
126		}
127		return price, nil
128	}
129	
130	// parsedRow 是导入文件中一行解析后的候选用量。
131	type parsedRow struct {
132		line int // 文件中的行号（含表头），用于报错定位
133		rec  usageRecord
134		t    time.Time
135	}
136	
137	func cmdUsageImport(dir, file string) error {
138		var reader io.ReadCloser
139		var source string
140		if file == "-" {
141			reader = io.NopCloser(os.Stdin)
142			source = "标准输入"
143		} else {
144			f, err := os.Open(file)
145			if err != nil {
146				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
147			}
148			reader = f
149			source = file
150		}
151		defer reader.Close()
152	
153		rows, parseErrs := parseUsageFile(reader)
154	
155		s, err := loadStore(dir)
156		if err != nil {
157			return err
158		}
159	
160		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
161		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
162		var problems []string
163		problems = append(problems, parseErrs...)
164	
165		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
166		var ordered []*parsedRow
167		newCount, dupCount := 0, 0
168	
169		for _, r := range rows {
170			cust, ok := s.Customers[r.rec.CustomerID]
171			if !ok {
172				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
173				continue
174			}
175			// 金额可行性预检：数量×固定单价不得溢出（金额单位：分）。
176			if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
177				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
178				continue
179			}
180	
181			// 去重判定同时对“库中已有”和“本文件内已出现”生效。
182			var existing *usageRecord
183			if inStore, ok := s.Usage[r.rec.ID]; ok {
184				existing = inStore
185			} else if inBatch, ok := accepted[r.rec.ID]; ok {
186				existing = &inBatch.rec
187			}
188	
189			if existing != nil {
190				if !sameUsage(existing, &r.rec, r.t) {
191					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
192						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
193					continue
194				}
195				dupCount++
196				continue
197			}
198	
199			// 全新标识：不得进入该客户已封账的 UTC 自然月。
200			month := r.t.UTC().Format("2006-01")
201			if s.sealed(r.rec.CustomerID, month) {
202				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
203					r.line, r.rec.CustomerID, month, r.rec.ID))
204				continue
205			}
206	
207			rr := r
208			accepted[r.rec.ID] = rr
209			ordered = append(ordered, rr)
210			newCount++
211		}
212	
213		if len(problems) > 0 {
214			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
215		}
216	
217		for _, r := range ordered {
218			rec := r.rec
219			s.Usage[rec.ID] = &rec
220		}
221		if err := s.save(); err != nil {
222			return err
223		}
224		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
225		return nil
226	}
227	
228	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
229	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
230		cr := csv.NewReader(r)
231		cr.FieldsPerRecord = 4
232		cr.TrimLeadingSpace = true
233	
234		header, err := cr.Read()
235		if err == io.EOF {
236			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
237		}
238		if err != nil {
239			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
240		}
241		for i := range header {
242			header[i] = strings.TrimSpace(header[i])
243		}
244		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
245			header[2] != "time" || header[3] != "quantity" {
246			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
247		}
248	
249		var rows []*parsedRow
250		var problems []string
251		line := 1
252		for {
253			rec, err := cr.Read()
254			if err == io.EOF {
255				break
256			}
257			line++
258			if err != nil {
259				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
260				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
261					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
262					break
263				}
264				continue
265			}
266			for i := range rec {
267				rec[i] = strings.TrimSpace(rec[i])
268			}
269	
270			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
271			if id == "" {
272				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
273				continue
274			}
275			if custID == "" {
276				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
277				continue
278			}
279			t, err := time.Parse(time.RFC3339, ts)
280			if err != nil {
281				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
282				continue
283			}
284			qty, err := strconv.ParseInt(qtyText, 10, 64)
285			if err != nil {
286				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
287				continue
288			}
289			if qty <= 0 {
290				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
291				continue
292			}
293	
294			rows = append(rows, &parsedRow{
295				line: line,
296				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
297				t:    t,
298			})
299		}
300		return rows, problems
301	}
302	
303	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
304	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
305	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
306		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
307			return false
308		}
309		et, err := time.Parse(time.RFC3339, existing.Time)
310		if err != nil {
311			return existing.Time == candidate.Time
312		}
313		return et.Equal(candidateT)
314	}
315	
316	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
317	func validMonth(m string) bool {
318		t, err := time.Parse("2006-01", m)
319		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
320			return false
321		}
322		return true
323	}
324	
325	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
326	func inMonth(rfc3339, month string) bool {
327		t, err := time.Parse(time.RFC3339, rfc3339)
328		if err != nil {
329			return false
330		}
331		return t.UTC().Format("2006-01") == month
332	}
333	
334	func cmdBillSettle(dir, customerID, month string) error {
335		if !validMonth(month) {
336			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
337		}
338		s, err := loadStore(dir)
339		if err != nil {
340			return err
341		}
342		cust, ok := s.Customers[customerID]
343		if !ok {
344			return fmt.Errorf("客户标识 %q 不存在", customerID)
345		}
346	
347		key := billKey(customerID, month)
348		if existing, ok := s.Bills[key]; ok {
349			// 幂等：同一客户同一月份重复结算，直接返回原账单，
350			// 不重新计费、不产生新账单、不落盘。
351			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
352			printBill(existing, cust)
353			return nil
354		}
355	
356		// 归集该客户 UTC 自然月内的全部用量，区间为左闭右开 [月初, 下月初)。
357		var inMonthRecs []*usageRecord
358		for _, u := range s.Usage {
359			if u.CustomerID == customerID && inMonth(u.Time, month) {
360				inMonthRecs = append(inMonthRecs, u)
361			}
362		}
363		if len(inMonthRecs) == 0 {
364			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
365		}
366		sortByInstant(inMonthRecs)
367	
368		lines := make([]billLine, 0, len(inMonthRecs))
369		var totalQty, totalFee int64
370		for _, u := range inMonthRecs {
371			lineFee, err := mul64(u.Quantity, cust.Price)
372			if err != nil {
373				return fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出，拒绝结算且不封账", u.ID, u.Quantity, cust.Price)
374			}
375			totalQty, err = add64(totalQty, u.Quantity)
376			if err != nil {
377				return fmt.Errorf("汇总数量溢出有符号 64 位整数范围，拒绝结算且不封账")
378			}
379			totalFee, err = add64(totalFee, lineFee)
380			if err != nil {
381				return fmt.Errorf("汇总金额溢出有符号 64 位整数范围，拒绝结算且不封账")
382			}
383			lines = append(lines, billLine{
384				UsageID:  u.ID,
385				Time:     u.Time,
386				Quantity: u.Quantity,
387				LineFee:  lineFee,
388			})
389		}
390	
391		b := &bill{
392			ID:         stableBillID(customerID, month),
393			CustomerID: customerID,
394			Month:      month,
395			TotalQty:   totalQty,
396			UnitPrice:  cust.Price,
397			TotalFee:   totalFee,
398			Lines:      lines,
399			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
400		}
401		s.Bills[key] = b
402	
403		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
404		if err := s.save(); err != nil {
405			delete(s.Bills, key)
406			return err
407		}
408		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
409		printBill(b, cust)
410		return nil
411	}
412	
413	func cmdBillShow(dir, customerID, month string) error {
414		if !validMonth(month) {
415			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
416		}
417		s, err := loadStore(dir)
418		if err != nil {
419			return err
420		}
421		cust, ok := s.Customers[customerID]
422		if !ok {
423			return fmt.Errorf("客户标识 %q 不存在", customerID)
424		}
425		b, ok := s.Bills[billKey(customerID, month)]
426		if !ok {
427			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
428		}
429		printBill(b, cust)
430		return nil
431	}
432	
433	func sortByInstant(us []*usageRecord) {
434		// 入参时间均已在载入/导入时校验为 RFC3339。
435		sort.Slice(us, func(i, j int) bool {
436			ti, _ := time.Parse(time.RFC3339, us[i].Time)
437			tj, _ := time.Parse(time.RFC3339, us[j].Time)
438			ui, uj := ti.UTC(), tj.UTC()
439			if !ui.Equal(uj) {
440				return ui.Before(uj)
441			}
442			return us[i].ID < us[j].ID
443		})
444	}
445	
446	// stableBillID 由（客户标识，月份）确定性派生：跨进程稳定，且客户/月份间唯一。
447	func stableBillID(customerID, month string) string {
448		sum := sha256.Sum256([]byte(customerID + "\x00" + month))
449		return "BILL-" + hex.EncodeToString(sum[:])[:16]
450	}
451	
452	func printBill(b *bill, cust *customer) {
453		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
454		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
455		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
456		fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
457		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
458		fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
459		fmt.Println("明细：")
460		for i, ln := range b.Lines {
461			fmt.Fprintf(stdout, "  %d. 用量标识=%s 时间=%s 数量=%d 小计=%d 分（%s）\n",
462				i+1, ln.UsageID, ln.Time, ln.Quantity, ln.LineFee, moneyFen(ln.LineFee))
463		}
464	}
