	return list
}

// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")

// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
// 按操作序号顺序累加——这正是各操作生效时的应付序列，全程整数运算。
func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
	payable = b.TotalFee
	for _, a := range adjs {
		if a.Revoked {
			continue
		}
		payable, err = addSigned64(payable, a.Amount)
		if err != nil {
			return 0, 0, err
		}
		if payable < 0 {
			return 0, 0, errPayableOutOfRange
		}
	}
	// payable 与 TotalFee 均在 [0, MaxInt64]，差值不会溢出。
	return payable - b.TotalFee, payable, nil
}

